using System.Collections.Generic;
using UnityEngine;

namespace WildLens.Environment
{
    /// <summary>
    /// Closed-loop trail centre-line in world space. Generated by the editor builder; used at runtime
    /// for spawning, location labels in the journal, and anything that needs "where is the trail".
    /// </summary>
    public class TrailPath : MonoBehaviour
    {
        [SerializeField] private List<Vector3> points = new List<Vector3>();
        [SerializeField] private float width = 1.8f;
        [SerializeField] private float markerSpacing = 60f;

        private float[] _cumulative;

        public IReadOnlyList<Vector3> Points => points;
        public float Width => width;
        public float MarkerSpacing => markerSpacing;
        public float Length { get { EnsureCache(); return _cumulative[_cumulative.Length - 1]; } }
        public int MarkerCount => Mathf.Max(1, Mathf.FloorToInt(Length / markerSpacing));

        public void SetPath(List<Vector3> newPoints, float newWidth, float newMarkerSpacing)
        {
            points = new List<Vector3>(newPoints);
            width = newWidth;
            markerSpacing = Mathf.Max(5f, newMarkerSpacing);
            _cumulative = null;
        }

        private void OnValidate() => _cumulative = null;

        private void EnsureCache()
        {
            if (_cumulative != null && _cumulative.Length == points.Count + 1) return;
            _cumulative = new float[points.Count + 1];
            for (int i = 0; i < points.Count; i++)
                _cumulative[i + 1] = _cumulative[i] + Vector3.Distance(points[i], points[(i + 1) % points.Count]);
        }

        /// <summary>Point at a distance along the loop (wraps).</summary>
        public Vector3 GetPoint(float distance)
        {
            if (points.Count == 0) return transform.position;
            EnsureCache();
            float len = _cumulative[_cumulative.Length - 1];
            if (len <= 0f) return points[0];
            distance = Mathf.Repeat(distance, len);
            for (int i = 0; i < points.Count; i++)
            {
                if (distance <= _cumulative[i + 1])
                {
                    float seg = _cumulative[i + 1] - _cumulative[i];
                    float t = seg > 0f ? (distance - _cumulative[i]) / seg : 0f;
                    return Vector3.Lerp(points[i], points[(i + 1) % points.Count], t);
                }
            }
            return points[0];
        }

        public Vector3 GetDirection(float distance)
        {
            Vector3 d = GetPoint(distance + 0.5f) - GetPoint(distance - 0.5f);
            d.y = 0f;
            return d.sqrMagnitude > 0.0001f ? d.normalized : Vector3.forward;
        }

        /// <summary>Horizontal distance from <paramref name="position"/> to the centre-line, plus distance along the loop.</summary>
        public float DistanceToTrail(Vector3 position, out float distanceAlong)
        {
            distanceAlong = 0f;
            if (points.Count < 2) return float.MaxValue;
            EnsureCache();
            float best = float.MaxValue;
            Vector2 p = new Vector2(position.x, position.z);
            for (int i = 0; i < points.Count; i++)
            {
                Vector3 a3 = points[i], b3 = points[(i + 1) % points.Count];
                Vector2 a = new Vector2(a3.x, a3.z), b = new Vector2(b3.x, b3.z);
                Vector2 ab = b - a;
                float t = ab.sqrMagnitude > 0f ? Mathf.Clamp01(Vector2.Dot(p - a, ab) / ab.sqrMagnitude) : 0f;
                float d = Vector2.Distance(p, a + ab * t);
                if (d < best)
                {
                    best = d;
                    distanceAlong = _cumulative[i] + (_cumulative[i + 1] - _cumulative[i]) * t;
                }
            }
            return best;
        }

        public float DistanceToTrail(Vector3 position) => DistanceToTrail(position, out _);

        /// <summary>Human readable location, e.g. "near trail marker 3" or "40 m off the trail near marker 2".</summary>
        public string DescribeLocation(Vector3 position)
        {
            float off = DistanceToTrail(position, out float along);
            int marker = Mathf.Clamp(Mathf.RoundToInt(along / markerSpacing), 0, MarkerCount);
            string place = marker == 0 || marker == MarkerCount ? "the trailhead" : "trail marker " + marker;
            return off < 6f ? "on the trail near " + place : Mathf.RoundToInt(off) + " m off the trail near " + place;
        }

        private void OnDrawGizmosSelected()
        {
            Gizmos.color = new Color(1f, 0.75f, 0.3f);
            for (int i = 0; i < points.Count; i++)
                Gizmos.DrawLine(points[i] + Vector3.up * 0.3f, points[(i + 1) % points.Count] + Vector3.up * 0.3f);
        }
    }
}
